def get_pairs_count(arr, n, sum):
    count = 0
    arr.sort()
    for i in range(n):
        left = i + 1
        right = n - 1
        while (left < right):
            if (arr[i] + arr[left] == sum):
                count += 1
                break
            elif (arr[i] + arr[left] > sum):
                right -= 1
            else:
                left += 1
    return count
```

